<?php
namespace App\Http\Controllers;
use App\Models\{Payment,MembershipTransaction};use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Support\Facades\DB;
class PaymentController extends Controller {private function admin(){abort_unless(auth()->user()->role==='admin',403);} public function create(MembershipTransaction $transaction){$this->admin();abort_unless(in_array($transaction->status,['Pending','Paid']),422);$transaction->load('member','payments');return view('payments.create',compact('transaction'));} public function store(Request $r,MembershipTransaction $transaction){$this->admin();$d=$r->validate(['amount'=>'required|numeric|gt:0','payment_method'=>'required|in:Cash,Bank Transfer,E-Wallet','payment_date'=>'required|date','notes'=>'nullable|string|max:1000']);DB::transaction(function()use($d,$transaction){$tx=MembershipTransaction::lockForUpdate()->findOrFail($transaction->id);abort_unless(in_array($tx->status,['Pending','Paid']),422,'Payments cannot be added to this transaction.');$balance=round((float)$tx->amount-(float)$tx->amount_paid,2);abort_if((float)$d['amount']>$balance,422,'Payment exceeds the outstanding balance.');Payment::create(['payment_reference'=>'PUH-PAY-'.now()->format('Ymd').'-'.Str::upper(Str::random(6)),'membership_transaction_id'=>$tx->id,'amount'=>$d['amount'],'payment_method'=>$d['payment_method'],'payment_date'=>$d['payment_date'],'notes'=>$d['notes']??null,'recorded_by'=>auth()->id()]);$paid=round((float)$tx->amount_paid+(float)$d['amount'],2);$tx->update(['amount_paid'=>$paid,'status'=>$paid >= (float)$tx->amount?'Paid':'Pending']);});return redirect()->route('transactions.show',$transaction)->with('success','Payment recorded.');} public function receipt(Payment $payment){$this->admin();$payment->load('transaction.member','transaction.level');return view('payments.receipt',compact('payment'));}}
